export const DIMENSIONS = ["day", "week", "region", "channel"] as const;
export const MEASURES = ["volume", "resolved", "median_age"] as const;

export type Dimension = (typeof DIMENSIONS)[number];
export type Measure = (typeof MEASURES)[number];

// Not every pairing is meaningful, and the ones that are not would each be a slow
// query with a confusing result rather than an error. Listing them is boring, and it
// is the whole reason the query surface stays finite.
export const PERMITTED: Record<Measure, readonly Dimension[]> = {
  volume: ["day", "week", "region", "channel"],
  resolved: ["day", "week", "region"],
  median_age: ["week", "region"],
};
